const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));document.querySelector('.links').classList.toggle('open',!expanded)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');document.querySelector('.links').classList.remove('open')}});const form=document.getElementById('contactForm');if(form)form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form);const body='Name: '+f.get('name')+'\nEmail: '+f.get('email')+'\n\n'+f.get('message');window.location.href='mailto:adewoleadewumi61@gmail.com?subject='+encodeURIComponent('Project enquiry from '+f.get('name'))+'&body='+encodeURIComponent(body);document.getElementById('formStatus').textContent='Your email app will open if configured. Please review your draft and send it there.'});